# EXPERIMENTAL (round 2b). Hybrid on real recordings (exercise 60 as in real.R, PRCP 10): M3, M3E_det (pipeline detector), HMMr (regime model, smoothed states), HYB (events = episodes of the smoothed regime probability, then M3E).
# In-sample only (the events of HYB and M3E_det use the whole record, so a forward score would need event detection on the head only). Run from the project root:  Rscript experiments/regimes/v2/hybrid_real.R
source("analysis/00_setup.R"); source("experiments/regimes/v2/lib2.R"); n_cores <- max(1L, min(5L, cfg$cores - 2L)); ev_ann <- fread("data/prcp_events.csv"); GATE <- 9
jobs <- list(); for (ds in c("exercise", "prcp")) { d <- load_dataset(ds, cfg); ids <- names(d$rr); if (ds == "exercise") { set.seed(21); ids <- sort(sample(ids, 60)) }
  for (id in ids) jobs[[length(jobs) + 1]] <- list(ds = ds, id = id, rr = d$rr[[id]], off = if (ds == "prcp") d$rec[[id]]$time[1] - d$rec[[id]]$rr[1] else 0) }
z_diag <- function(z, gm, ctl) { k <- which(is.finite(z) & gm < ctl$diag_gate_max); z <- z[k]; n <- length(z); c(ks = unname(ks.test(pnorm(z), "punif")$statistic) < 1.36 / sqrt(n), pacf = sum(abs(as.numeric(pacf(z, lag.max = min(ctl$pacf_lag_max, max(1, n - 5)), plot = FALSE)$acf)) > qnorm(.975) / sqrt(n))) }
t50 <- function(x, t, t_on, rest_mean, end_mean) { x <- as.numeric(stats::filter(x, rep(1 / 5, 5), sides = 2)); x[is.na(x)] <- 0; half <- (rest_mean + end_mean) / 2; k <- which(t >= t_on & sign(end_mean - rest_mean) * (x - half) >= 0)[1]; if (is.na(k)) NA_real_ else t[k] - t_on }
one <- function(job) {
  series <- prepare_series(job$rr); dy <- series$dy; tt <- cumsum(dy); ctl <- series$control; gm <- gate_mult(dy, ctl); n_eff <- sum(gm < ctl$lik_gate_max); expl <- function(l) l - n_eff / 2 * (log(2 * pi) + 1)
  base <- fit_ext(series); cp <- cp_search(series, base, min_gain = -Inf); open <- !is.null(cp) && cp$gain >= GATE; ll0 <- expl(base$run()$LL_star); rows <- list()
  ex_ev <- if (job$ds == "exercise") events_from_rr(dy, "exercise", cfg$segmentation) else NULL; mode <- c(exercise = "exercise", prcp = "tilt")[[job$ds]]; ev_det <- events_from_rr(dy, mode, cfg$segmentation)
  stats <- function(m, xp, xs, z, ll, n_par, tau_p, onsets) { dg <- z_diag(z, gm, ctl); row <- data.table(ds = job$ds, id = job$id, model = m, ks_ok = dg[["ks"]], pacf = dg[["pacf"]], dLL = ll - ll0, dAIC = (ll - ll0) - (n_par - 5), tau_p = tau_p, n_onsets = length(onsets), gain = if (is.null(cp)) NA_real_ else cp$gain)
    if (!is.null(ex_ev)) { t_on <- ex_ev$t0[1]; t_end <- ex_ev$t1[1]; rest <- tt >= cfg$exercise$rest_skip_s & tt < t_on - 5; endw <- tt >= t_end - cfg$exercise$end_window_s & tt <= t_end
      if (sum(rest) > 20 && sum(endw) > 5) row[, `:=`(t50_vagal = t50(xp, tt, t_on, mean(xp[rest]), mean(xp[endw])), t50_symp = t50(xs, tt, t_on, mean(xs[rest]), mean(xs[endw])), d_vagal = mean(xp[endw]) - mean(xp[rest]), d_symp = mean(xs[endw]) - mean(xs[rest]))] }
    if (job$ds == "prcp") { a1 <- ev_ann[as.character(ev_ann$id) == job$id & is.finite(onset_s)]; an <- a1$onset_s - job$off; ret <- a1[is.finite(return_s), return_s] - job$off; every <- c(an, ret)
      row[, `:=`(n_annot = length(an), hits = if (length(onsets)) sum(vapply(an, function(a) min(abs(onsets - a)) <= 30, TRUE)) else 0L, false_alarms = if (length(onsets)) sum(vapply(onsets, function(o) all(abs(every - o) > 30), TRUE)) else 0L)] }
    rows[[m]] <<- row }
  e <- state_estimates(base, TRUE); stats("M3", e$xp, e$xs, e$r$std_innov, ll0, 5, base$tau_p, numeric(0))
  if (!is.null(ev_det)) { f <- fit_ext(series, list(inputs = list(events = ev_det))); if (isTRUE(f$ok)) { e <- state_estimates(f, TRUE); stats("M3E_det", e$xp, e$xs, e$r$std_innov, expl(e$r$LL_star), 5 + 2 * nrow(ev_det), f$tau_p, ev_det$t0) } }
  if (open) { h <- fit_regime(series, 2, cp, base, 7, 0.7, recip = 20); if (isTRUE(h$ok)) { r <- h$run(smooth = TRUE); Ws <- regime_smooth(r$W, r$A, h$p$Pi); stats("HMMr", r$Xs_p, r$Xs_s, r$z, r$LL, h$n_par, h$tau_p, regime_onsets2(Ws, tt))
      ev_h <- regime_episodes(Ws, tt, max_ev = 8); if (!is.null(ev_h)) { f <- tryCatch(fit_ext(series, list(inputs = list(events = ev_h))), error = function(e) NULL); if (!is.null(f) && isTRUE(f$ok)) { e <- state_estimates(f, TRUE); stats("HYB", e$xp, e$xs, e$r$std_innov, expl(e$r$LL_star), 5 + 2 * nrow(ev_h), f$tau_p, ev_h$t0) } } } }
  rbindlist(rows, fill = TRUE)[, open := open] }
log_msg("Hybrid, real data | %d recordings", length(jobs)); res <- rbindlist(drop_failed(map_recordings(jobs, one, n_cores), "recording"), fill = TRUE); saveRDS(res, "experiments/regimes/v2/_out/hybrid_real.rds"); cat("Saved", nrow(res), "rows\n")
fb <- res[model == "M3", .(ds, id, k0 = ks_ok, p0 = pacf, t0 = tau_p, v0 = t50_vagal, s0 = t50_symp, dv0 = d_vagal, ds0 = d_symp)]; g <- merge(res, fb, by = c("ds", "id"))
cat("\nIn-sample (states smoothed; HMMr and HYB where the gate is open, otherwise they equal M3 and are not counted below):\n")
print(g[model %in% c("M3", "M3E_det", "HMMr", "HYB"), .(n = .N, ks_pass = round(100 * mean(ks_ok)), pacf = round(mean(pacf), 1), dLL = round(median(dLL), 1), dAIC = round(median(dAIC), 1), tau_p = round(median(tau_p), 1)), by = .(ds, model)][order(ds, match(model, c("M3", "M3E_det", "HMMr", "HYB")))])
cat("\nExercise realism:\n"); print(g[ds == "exercise" & !is.na(t50_vagal) & !is.na(t50_symp), .(n = .N, t50_vagal = round(median(t50_vagal), 1), t50_symp = round(median(t50_symp), 1), vagal_faster = round(100 * mean(t50_vagal < t50_symp)), expected_signs = round(100 * mean(d_vagal < 0 & d_symp > 0))), by = model][order(match(model, c("M3", "M3E_det", "HMMr", "HYB")))])
cat("\nPRCP: annotated onsets found within 30 s (62 in total), detections, detections without annotated change:\n"); print(g[ds == "prcp", .(recordings = .N, hits = sum(hits, na.rm = TRUE), detections = sum(n_onsets), no_annotation = sum(false_alarms, na.rm = TRUE)), by = model][order(match(model, c("M3", "M3E_det", "HMMr", "HYB")))])
